// استخراج بيانات الرسالة من Telegram
const msg = $input.item.json.message;
if (!msg) return [{ json: { chatId: '', text: '', firstName: 'صديقي', username: '' } }];

const chatId = String(msg.chat.id);
const text = (msg.text || '').trim();
const firstName = (msg.from && msg.from.first_name) ? msg.from.first_name : 'صديقي';
const username = (msg.from && msg.from.username) ? msg.from.username : '';

return [{ json: { chatId, text, firstName, username } }];
